TEMP_MODULE="/data/nh.ko"
echo "$MODULE_BASE64" | base64 -d > "$TEMP_MODULE"


ERROR_MSG=$(insmod "$TEMP_MODULE" 2>&1)
if [ $? -eq 0 ]; then
  echo -e "${COLOR_GREEN}操作成功:${NC} DT驱动已经成功加载。"
  rm -f "$TEMP_MODULE"
else
  echo -e "${COLOR_RED}失败，重启。${RESET_SEQ}"
  echo "5 秒后自动重启设备..."
  sleep 5
  reboot
  exit 1
fi